/* Whether the board's kvdb survives a reset.  It decides what a reboot means:
 * with a non-persistent store, rebooting wipes web.host/web.fp/web.token and
 * the board cannot dial back in -- it has to be re-paired over the serial
 * console.  Turning that into a surprise would be unkind. */
let boardPersistent = null;

/* Previous link.connected, so an attach can be told from a state push that
 * merely repeats it. */
let lastLinkConnected = null;

/* The pairing note used to assert that the store was persistent.  That is a
 * property of whatever firmware is on the board, not of this page, and the two
 * fell out of step the moment the flash backend was dropped: the page went on
 * promising that Wi-Fi and web.* would survive a reboot while the board itself
 * was answering "in-memory only".  So it is read from the board, the same
 * value the kvdb card and the reboot warning already use, and says it does not
 * know until the board has told it. */

function renderPersistence() {
  const el = $('pair-persist');
  if (!el) { return; }
  if (boardPersistent === true) {
    el.textContent = '板子报告 kvdb 持久：配对一次即可，'
      + 'Wi-Fi 与 web.* 会跨重启保留，重启后板子自己拨回来。';
  } else if (boardPersistent === false) {
    el.textContent = '板子报告 kvdb 不持久（flash 后端未启用）：'
      + '每次重启都要重新配对，重启后板子不会自己拨回来。';
  } else {
    el.textContent = '配对能不能只做一次，取决于板子的 kvdb 是否持久——'
      + '板子接入后这里会显示它自己报的实际情况。';
  }
}

